/// Grass block sides: the untinted dirt part's mean color, the tinted fringe's share of the texture, and the
/// fringe overlay's mean gray. Side color for tint T = (1 - fringe) * base + fringe * gray * T.
let lodGrassSideBase = SIMD3<Float>(0.508, 0.364, 0.253)
let lodGrassSideFringe: Float = 0.176
let lodGrassOverlayGray: Float = 0.606

